-- bench7 schema (Postgres 18). Same for every framework.
--
-- Rules:
--   * every primary key is a UUIDv7, generated by the APP (or the seed); the
--     id is time-ordered, so "id < $cursor ORDER BY id DESC" is newest-first
--     keyset pagination, and created_at = uuid_extract_timestamp(id).
--   * NO column defaults anywhere: every INSERT names and supplies every
--     column (counters 0, flags false, NULLs explicit).
--   * body columns are STORAGE EXTERNAL: out of line, uncompressed, so the
--     3 KB payload is real on disk and left(body, 400) reads one TOAST chunk.
--   * secondary indexes and foreign keys are created after the bulk load by
--     db/constraints.sql (standard bulk-load practice); they exist during runs.

CREATE TABLE IF NOT EXISTS users (
  id               uuid        PRIMARY KEY,
  username         text        NOT NULL,
  email            text        NOT NULL,
  display_name     text        NOT NULL,
  bio              text        NOT NULL,
  avatar_url       text,
  location         text,
  website          text,
  is_verified      boolean     NOT NULL,
  is_private       boolean     NOT NULL,
  status           smallint    NOT NULL CHECK (status IN (0, 1, 2)),     -- 0 active, 1 suspended, 2 deleted
  followers_count  bigint      NOT NULL,
  following_count  bigint      NOT NULL,
  posts_count      bigint      NOT NULL,
  created_at       timestamptz NOT NULL,
  updated_at       timestamptz NOT NULL,
  last_active_at   timestamptz
) WITH (fillfactor = 90);

CREATE TABLE IF NOT EXISTS posts (
  id             uuid        PRIMARY KEY,
  user_id        uuid        NOT NULL,
  reply_to_id    uuid,
  visibility     smallint    NOT NULL CHECK (visibility IN (0, 1)),        -- 0 public, 1 private
  title          text        NOT NULL,
  body           text        NOT NULL,
  lang           text        NOT NULL,
  media_url      text,
  like_count     bigint      NOT NULL,
  comment_count  bigint      NOT NULL,
  share_count    bigint      NOT NULL,
  view_count     bigint      NOT NULL,
  is_edited      boolean     NOT NULL,
  created_at     timestamptz NOT NULL,
  updated_at     timestamptz NOT NULL,
  deleted_at     timestamptz
) WITH (fillfactor = 90);  -- room for HOT counter updates (like_count, comment_count)
ALTER TABLE posts ALTER COLUMN body SET STORAGE EXTERNAL;

-- one row per user pair (user_a_id < user_b_id), upserted by the message batcher
CREATE TABLE IF NOT EXISTS conversations (
  id                    uuid        PRIMARY KEY,
  user_a_id             uuid        NOT NULL,
  user_b_id             uuid        NOT NULL,
  last_message_id       uuid        NOT NULL,
  last_message_preview  text        NOT NULL,
  last_message_at       timestamptz NOT NULL,
  message_count         bigint      NOT NULL,
  created_at            timestamptz NOT NULL,
  updated_at            timestamptz NOT NULL,
  CHECK (user_a_id < user_b_id)
) WITH (fillfactor = 80);

CREATE TABLE IF NOT EXISTS messages (
  id               uuid        PRIMARY KEY,
  conversation_id  uuid        NOT NULL,
  sender_id        uuid        NOT NULL,
  recipient_id     uuid        NOT NULL,
  content_type     smallint    NOT NULL CHECK (content_type IN (0, 1, 2, 3)),  -- text, image, video, file
  body             text        NOT NULL,
  attachment_url   text,
  created_at       timestamptz NOT NULL,
  read_at          timestamptz,
  edited_at        timestamptz,
  deleted_at       timestamptz
);
ALTER TABLE messages ALTER COLUMN body SET STORAGE EXTERNAL;

CREATE TABLE IF NOT EXISTS likes (
  id          uuid        PRIMARY KEY,
  user_id     uuid        NOT NULL,
  post_id     uuid        NOT NULL,
  created_at  timestamptz NOT NULL,
  UNIQUE (user_id, post_id)
);

-- seed facts + watermark: reset.sql deletes everything written after the seed
CREATE TABLE IF NOT EXISTS bench_meta (
  k text PRIMARY KEY,
  v text NOT NULL
);
